SELECT WFL.TRADE_ID tradeId,
WFL.WORKFLOW_STATUS tradeStatus,
#{validStatus_02} tradeStatus,
#{validStatus_03} tradeStatus,
case WFL.TRADE_STATUS when '03' then #{validStatus_03} else #{validStatus_02} end as tradeStatus,
WFLDEAL.ENTRUST_ID entrustId, PP.PORTFOLIO_ID portfolioId, PP.PORTFOLIO_NAME portfolioName, WFL.FINPROD_TYPE2 finprodType, WFL.FINPROD_ID finprodId, FINTYPE.TYPE_6 type1,
FINTYPE.TYPE_9 type9, FINTYPE.TYPE_10 type10, FINTYPE.TYPE_11 type11,
FIN.FINPROD_MARKET_ID finprodMarketId, FIN.FINPROD_NAME finprodName, WFL.PS ps, WFL.TRADE_AMT tradeAmt, WFL.CCY ccy, WFL.TRADE_DATE tradeDate, WFL.REMARK remark
FROM TRD_PRODUCT_DEAL WFL LEFT JOIN TRD_PRODUCT_DEAL_ADD WFLDEAL ON WFL.TRADE_ID = WFLDEAL.TRADE_ID LEFT JOIN PA_TRD_PRODUCT_DEAL WFLPA ON WFL.TRADE_ID = WFLPA.TRADE_ID LEFT JOIN PTL_TRADE PT ON IFNULL(WFL.P_TRADE_ID,WFL.TRADE_ID) = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
FROM WFL_TRD_PRODUCT_DEAL WFL LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD WFLDEAL ON WFL.TRADE_ID = WFLDEAL.TRADE_ID LEFT JOIN WFL_PA_TRD_PRODUCT_DEAL WFLPA ON WFL.TRADE_ID = WFLPA.TRADE_ID LEFT JOIN PTL_PORTFOLIO PP ON WFLDEAL.PORTFOLIO_ID = PP.PORTFOLIO_ID
LEFT JOIN FIN_PRODUCT FIN ON WFL.FINPROD_ID = FIN.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE FINTYPE ON FIN.FINPROD_ID = FINTYPE.FINPROD_ID
PP.INVEST_YESORNO = 'Y'
AND (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
AND WFL.FINPROD_TYPE2 = #{finprodType2}
AND (WFLPA.PA_BUSS_TYPE = #{pingTypeBuy} OR WFLPA.PA_BUSS_TYPE = #{pingTypeSale})
AND ( pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item}
)
AND WFLDEAL.ENTRUST_ID = #{entrustId}
AND FIN.FINPROD_MARKET_ID = #{finprodId}
AND FINTYPE.TYPE_6 = #{finprodType}
AND FINTYPE.TYPE_9 in
#{item}
AND FINTYPE.TYPE_10 in
#{item}
AND FINTYPE.TYPE_11 in
#{item}
AND WFL.PS IN
#{item}
AND WFL.TRADE_STATUS =#{validStatus_01} AND WFL.IS_CANCEL != 'Y'
AND WFL.TRADE_STATUS =#{validStatus_03} AND WFL.IS_CANCEL != 'Y'
AND WFL.IS_CANCEL != 'Y'
AND WFL.WORKFLOW_STATUS =#{status}
AND WFL.TRADE_DATE >= STR_TO_DATE(#{tradeDateBegin},'%Y-%m-%d')
AND WFL.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd},'%Y-%m-%d')
UNION ALL SELECT WFL.TRADE_ID tradeId, WFL.WORKFLOW_STATUS tradeStatus, WFLDEAL.ENTRUST_ID entrustId, pp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, WFL.FINPROD_TYPE2 finprodType, WFL.FINPROD_ID finprodIdHide, FINTYPE.TYPE_6 type1,
FINTYPE.TYPE_9 type9, FINTYPE.TYPE_10 type10, FINTYPE.TYPE_11 type11,
FIN.FINPROD_MARKET_ID finprodId, FIN.FINPROD_NAME finprodName, WFL.PS ps, WFL.TRADE_AMT tradeAmt, WFL.CCY ccy, WFL.TRADE_DATE tradeDate, WFL.REMARK remark FROM WFL_TRD_PRODUCT_DEAL WFL LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD WFLDEAL ON WFL.TRADE_ID = WFLDEAL.TRADE_ID LEFT JOIN WFL_PA_TRD_PRODUCT_DEAL WFLPA ON WFL.TRADE_ID = WFLPA.TRADE_ID LEFT JOIN FIN_PRODUCT FIN ON WFL.FINPROD_ID = FIN.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE FINTYPE ON FIN.FINPROD_ID = FINTYPE.FINPROD_ID LEFT JOIN PTL_PORTFOLIO PP ON WFLDEAL.PORTFOLIO_ID = PP.PORTFOLIO_ID
PP.INVEST_YESORNO = 'Y'
AND (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
AND WFL.FINPROD_TYPE2 = #{finprodType2}
